export type Task = {
    id: string;
    createdAt: Date;
    updatedAt: Date;
    /**
     * The Owner: the person who answers for the work, and the only reader of private work. Null when it has none: a Soko Bot started it on its own, or its Owner deleted their account.
     */
    ownerId: string | null;
    /**
     * The Owner: the person who answers for the work, and the only reader of private work. Null when it has none: a Soko Bot started it on its own, or its Owner deleted their account.
     */
    owner: UserSummary | null;
    /**
     * Deprecated. Use ownerId instead.
     *
     * @deprecated
     */
    userId: string | null;
    /**
     * Deprecated. Use owner instead.
     *
     * @deprecated
     */
    user: UserSummary | null;
    organizationId: string | null;
    organization: OrganizationSummary;
    projectId: string | null;
    /**
     * Linked project name and logo. Null when the task has no project.
     */
    project: ProjectSummary | null;
    /**
     * Marketplace coworker assignee. Null when assigned to a user, a Soko Bot, or unset. Prefer `assignee`.
     */
    assigneeId: string | null;
    /**
     * Soko Bot assignee. Null when assigned to a coworker, a user, or unset. Prefer `assignee`.
     */
    assigneeSokoBotId: string | null;
    /**
     * Workspace-member assignee id. Null when assigned to a coworker, a Soko Bot, or unset. Prefer `assignee`.
     */
    assigneeUserId: string | null;
    /**
     * Discriminated assignee: coworker, workspace member, Soko Bot, or unassigned.
     */
    assignee: TaskAssigneeCoworker | TaskAssigneeUser | TaskAssigneeSokoBot | null;
    /**
     * Workspace members on the Task (via @ mention or self-subscribe), in join order. Owner and assignee are omitted unless they also joined. Empty until someone joins.
     */
    participants: Array<TaskParticipant>;
    /**
     * Deprecated marketplace coworker assignee. Null when the assignee is a Soko Bot.
     *
     * @deprecated
     */
    coworkerId: string | null;
    /**
     * Deprecated marketplace coworker summary. Null when the assignee is a Soko Bot.
     *
     * @deprecated
     */
    coworker: CoworkerSummary | null;
    /**
     * Who made it: a person, a Coworker or a Soko Bot. Null when the person who made it deleted their account.
     */
    creator: WorkCreatorUser | WorkCreatorCoworker | WorkCreatorSokoBot | null;
    /**
     * Deprecated. Use creator when type is sokoBot. Only set when a Soko Bot created the task.
     *
     * @deprecated
     */
    sokoBotId: string | null;
    /**
     * Deprecated. Use creator when type is sokoBot. Only set when a Soko Bot created the task.
     *
     * @deprecated
     */
    sokoBot: SokoBotSummary | null;
    tags?: TaskTags;
    /**
     * Sequence number within the project. Null when the task has no project.
     */
    number: number | null;
    /**
     * Project identifier and number, e.g. SOK-123. Null when the task has no project.
     */
    identifier: string | null;
    name: string;
    description: string | null;
    status: TaskStatus & unknown;
    visibility: TaskVisibility;
    priority: TaskPriority;
    /**
     * Target status after vendor workspace grant approval. Exposed on the task API only while status is GRANT_PENDING; null otherwise.
     */
    grantResumeStatus: 'DRAFT' | 'READY' | null;
    /**
     * Vendor grant blocking this task. Exposed on the task API only while status is GRANT_PENDING so integrators can correlate the parked task with the grant; null otherwise.
     */
    pendingVendorGrantId: string | null;
    /**
     * The one time a Queued Task moves to Ready. Set only while the Task is Queued; it never repeats.
     */
    runAt: Date | null;
    /**
     * Task Schedule whose Run created this Task. Read-only; null when it was created by hand or its schedule was deleted.
     */
    scheduleId: string | null;
    credits: number;
    events: Array<TaskEvent>;
    jobs: Array<JobSummary>;
    workspace: WorkspaceSummary;
    share: TaskShare | null;
    links: Array<TaskLink>;
    /**
     * Files uploaded to this task (newest first).
     */
    files: Array<TaskFile>;
    /**
     * Statuses the requesting actor may move this task to right now, in display order and excluding the current one. Computed per actor: a user never sees coworker-set statuses such as INPUT_REQUIRED or APPROVAL_REQUIRED. POST /tasks/{id}/events rejects a user status outside this list.
     */
    selectableStatuses: Array<TaskStatus>;
};

