/**
 * PUBLIC (default) or PRIVATE. Private Tasks are visible only to the owner, that owner's Soko Bot, and the assigned coworker's vendor family. Set at create; immutable.
 */
export const TaskVisibility = { PUBLIC: 'PUBLIC', PRIVATE: 'PRIVATE' } as const;

/**
 * PUBLIC (default) or PRIVATE. Private Tasks are visible only to the owner, that owner's Soko Bot, and the assigned coworker's vendor family. Set at create; immutable.
 */
export type TaskVisibility = typeof TaskVisibility[keyof typeof TaskVisibility];

/**
 * URGENT, HIGH, MEDIUM, LOW, or NONE (default).
 */
export const TaskPriority = {
    URGENT: 'URGENT',
    HIGH: 'HIGH',
    MEDIUM: 'MEDIUM',
    LOW: 'LOW',
    NONE: 'NONE'
} as const;

/**
 * URGENT, HIGH, MEDIUM, LOW, or NONE (default).
 */
export type TaskPriority = typeof TaskPriority[keyof typeof TaskPriority];

export type TaskEvent = {
    id: string;
    taskId: string;
    createdAt: Date;
    updatedAt: Date;
    actor: TaskEventActor;
    /**
     * Deprecated. Use actor when type is user.
     *
     * @deprecated
     */
    userId?: string | null;
    /**
     * Deprecated. Prefer actor. Emitted only when the preferred actor is user (prefer order: sokoBot → coworker → user). Legacy multi-FK rows may still set other actor FKs without this summary.
     *
     * @deprecated
     */
    user?: {
        id: string;
        name: string;
        image?: string | null;
    } | null;
    /**
     * Deprecated. Use actor when type is coworker.
     *
     * @deprecated
     */
    coworkerId?: string | null;
    /**
     * Deprecated. Prefer actor. Emitted only when the preferred actor is coworker (prefer order: sokoBot → coworker → user). Legacy multi-FK rows may still set other actor FKs without this summary.
     *
     * @deprecated
     */
    coworker?: {
        id: string;
        name: string;
        image?: string | null;
        slug: string;
    } | null;
    /**
     * Deprecated. Use actor when type is sokoBot.
     *
     * @deprecated
     */
    sokoBotId?: string | null;
    /**
     * Deprecated. Prefer actor. Emitted only when the preferred actor is sokoBot (prefer order: sokoBot → coworker → user). Legacy multi-FK rows may still set other actor FKs without this summary.
     *
     * @deprecated
     */
    sokoBot?: {
        id: string;
        name: string | null;
        avatarSeed: string | null;
        avatarImageUrl: string | null;
        avatarStyleId?: string | null;
        owner: UserSummary | null;
    } | null;
    transactionId?: string | null;
    credits?: number | null;
    comment?: string | null;
    authenticationUrl?: string | null;
    channel: Channel;
    origin: Channel & unknown;
    status?: TaskEventStatus | null;
};

/**
 * Actor that produced the event. Null when no actor FK is set.
 */
export type TaskEventActor = TaskEventActorUser | TaskEventActorCoworker | TaskEventActorSokoBot | null;

export type TaskEventActorUser = {
    type: 'user';
    id: string;
    user: UserSummary;
};

export type TaskEventActorCoworker = {
    type: 'coworker';
    id: string;
    coworker: CoworkerSummary;
};

export type TaskEventActorSokoBot = {
    type: 'sokoBot';
    id: string;
    sokoBot: SokoBotSummary;
};

/**
 * Channel of the task event. Defaults to SOKOSUMI when neither channel nor deprecated origin is set.
 */
export const Channel = {
    SLACK: 'SLACK',
    TEAMS: 'TEAMS',
    EMAIL: 'EMAIL',
    LINEAR: 'LINEAR',
    GITHUB: 'GITHUB',
    WHATSAPP: 'WHATSAPP',
    TELEGRAM: 'TELEGRAM',
    SIGNAL: 'SIGNAL',
    DISCORD: 'DISCORD',
    CHAT: 'CHAT',
    MESSENGER: 'MESSENGER',
    SOKOSUMI: 'SOKOSUMI',
    UNKNOWN: 'UNKNOWN'
} as const;

/**
 * Channel of the task event. Defaults to SOKOSUMI when neither channel nor deprecated origin is set.
 */
export type Channel = typeof Channel[keyof typeof Channel];

export const TaskEventStatus = {
    DRAFT: 'DRAFT',
    QUEUED: 'QUEUED',
    READY: 'READY',
    GRANT_PENDING: 'GRANT_PENDING',
    INPUT_REQUIRED: 'INPUT_REQUIRED',
    APPROVAL_REQUIRED: 'APPROVAL_REQUIRED',
    AUTHENTICATION_REQUIRED: 'AUTHENTICATION_REQUIRED',
    OUT_OF_CREDITS: 'OUT_OF_CREDITS',
    CREDITS_TOPPED_UP: 'CREDITS_TOPPED_UP',
    RUNNING: 'RUNNING',
    AWAITING_EXTERNAL: 'AWAITING_EXTERNAL',
    COMPLETED: 'COMPLETED',
    FAILED: 'FAILED',
    CANCELED: 'CANCELED',
    CREATED: 'CREATED'
} as const;

export type TaskEventStatus = typeof TaskEventStatus[keyof typeof TaskEventStatus];

export type JobSummary = {
    id: string;
    createdAt: Date;
    updatedAt: Date;
    completedAt?: Date | null;
    agentId: string;
    /**
     * The Owner: the person who answers for the work, and the only reader of private work. Null when it has none: a Soko Bot started it on its own, or its Owner deleted their account.
     */
    ownerId: string | null;
    /**
     * The Owner: the person who answers for the work, and the only reader of private work. Null when it has none: a Soko Bot started it on its own, or its Owner deleted their account.
     */
    owner: UserSummary | null;
    /**
     * Who made it: a person, a Coworker or a Soko Bot. Null when the person who made it deleted their account.
     */
    creator: WorkCreatorUser | WorkCreatorCoworker | WorkCreatorSokoBot | null;
    /**
     * Deprecated. Use ownerId instead.
     *
     * @deprecated
     */
    userId: string | null;
    /**
     * Deprecated. Use owner instead.
     *
     * @deprecated
     */
    user: UserSummary | null;
    organizationId?: string | null;
    organization?: OrganizationSummary;
    projectId?: string | null;
    workspace: WorkspaceSummary;
    taskId?: string | null;
    name?: string | null;
    jobType: JobType;
    status: SokosumiJobStatus;
    credits: number;
    onChainStatus?: OnChainJobStatus | null;
    onChainTransactionHash?: string | null;
    result?: string | null;
    resultHash?: string | null;
    blockchainIdentifier?: string | null;
    payByTime?: Date | null;
    submitResultTime?: Date | null;
    unlockTime?: Date | null;
    externalDisputeUnlockTime?: Date | null;
    sellerVkey?: string | null;
    /**
     * True when the job status is settled for UI (FREE: completed; PAID: past external dispute unlock).
     */
    jobStatusSettled: boolean;
};

export type WorkspaceSummary = {
    id: string;
    organizationId: string | null;
    organization: {
        id: string;
        name: string;
        slug: string;
    } | null;
};

