export type WorkspaceCalendarEntry = {
    scheduledAt: Date;
    originalScheduledAt?: Date | null;
} & (WorkspaceCalendarItem | SocialPostCalendarItem);

export type WorkspaceCalendarItem = {
    /**
     * The Task Schedule Run this item shows, or the Task for a RUN_AT item
     */
    id: string;
    /**
     * RUN is a Task Schedule Run; RUN_AT is a Queued Task that starts at its Run at
     */
    kind: 'RUN' | 'RUN_AT';
    /**
     * Task Schedule the Run belongs to; null for RUN_AT
     */
    scheduleId: string | null;
    /**
     * Task Schedule revision observed with this Run; the expectedRevision for changing it. Null for RUN_AT.
     */
    scheduleRevision: number | null;
    /**
     * Whether the caller may skip, move, or restore this Run through PATCH /v1/tasks/schedules/{id}/runs/{runId}
     */
    canChangeRun: boolean;
    /**
     * Task the Run created (null while planned), or the RUN_AT Task itself
     */
    taskId: string | null;
    /**
     * Name of the Task the Run created, or of the one it creates
     */
    taskName: string;
    /**
     * Status of the Task the Run created, or QUEUED for RUN_AT; null while a Run is planned
     */
    taskStatus: TaskStatus | null;
    taskAssigneeId: string | null;
    taskAssigneeUserId?: string | null;
    /**
     * Owner of the Task Schedule and the Tasks it creates; null when it has none
     */
    taskOwnerId: string | null;
    /**
     * Effective time at which the item appears in the Calendar
     */
    scheduledAt: Date;
    /**
     * The rule's time for this Run; differs from scheduledAt when the Run was moved
     */
    originalScheduledAt: Date | null;
    /**
     * PLANNED is still to come (moved Runs and RUN_AT Tasks too); RELEASED created its Task. Skipped Runs are not on the Calendar.
     */
    state: 'PLANNED' | 'RELEASED';
    /**
     * Canonical Calendar source identity
     */
    sourceId: string;
    /**
     * Workspace captured as the Calendar source
     */
    sourceWorkspaceId: string;
    sourceType: 'WORKSPACE' | 'PROJECT';
    /**
     * Project captured as the Calendar source, when applicable
     */
    sourceProjectId: string | null;
};

export type SocialPostCalendarItem = {
    kind: 'socialPost';
    id: string;
    postId: string;
    quotedPostId: string | null;
    /**
     * A due quote waiting without a time limit for its quoted post to publish. Derived from its schedule and the quoted post's state; no publish attempt is consumed.
     */
    waitingForQuotedPost?: boolean;
    /**
     * Quote dependency failure. A queued post becomes FAILED; drafts retain approval requirements. Pick another post, remove the quote, or retry after a failed target recovers.
     */
    needsAttentionReason: string | null;
    /**
     * Total posts including the main text/media (1 for a single post).
     */
    threadPartCount: number;
    publishedThreadPartCount: number;
    failedThreadPartPosition: number | null;
    /**
     * Some but not all thread parts have confirmed X ids. Terminal failures retain FAILED; retry resumes unpublished parts.
     */
    partiallyPublished: boolean;
    provider: 'x' | 'linkedin' | 'facebook' | 'instagram' | 'tiktok' | 'youtube';
    text: string;
    status: 'DRAFT' | 'NEEDS_APPROVAL' | 'SCHEDULED' | 'PUBLISHING' | 'PUBLISHED' | 'FAILED' | 'MISSED' | 'CANCELED';
    revision: number;
    externalHandle: string | null;
    /**
     * Profile picture copy in Sokosumi storage
     */
    avatarUrl: string | null;
    projectName: string;
    scheduledByName: string | null;
    scheduledByImage: string | null;
    attachmentCount: number;
    /**
     * The post's first attachment, for a thumbnail.
     */
    previewMedia: {
        fileUrl: string;
        kind: 'image' | 'gif' | 'video';
    } | null;
    scheduledAt: Date;
    /**
     * Latest publish attempt outcome and error kind for Failed and Missed chips. Never the raw provider error.
     */
    lastAttempt: {
        outcome: string | null;
        errorKind: string | null;
    } | null;
    sourceId: string;
    sourceProjectId: string;
    sourceWorkspaceId: string;
    sourceType: 'PROJECT';
};

